INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-05', 'Journeys and travel', '{"part1": [{"topic": "your neighbourhood", "questions": ["What kind of area do you live in?", "What do you like to do in your neighbourhood?", "Would you like to move to a different area in the future?"]}, {"topic": "transport", "questions": ["How do you usually get to work or school?", "Do you prefer travelling by bus or by train?", "Is public transport good where you live?"]}], "part2": {"topic": "a memorable journey", "cue": "Describe a journey that you remember well.", "points": ["where you were going", "how you travelled", "who you were with"], "explain": "and explain why you remember this journey so well.", "rounding": "Do you often make journeys like this?"}, "part3": {"topic": "travel and transport", "questions": ["Why do people enjoy travelling to new places?", "How has the way people travel changed in your country in recent years?", "Should governments spend more money on public transport or on roads?", "What are the effects of mass tourism on popular destinations?", "Do you think people will travel more or less in the future?"]}}'::jsonb, now() + interval '1 seconds') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-06', 'Work and ambition', '{"part1": [{"topic": "your studies or work", "questions": ["What subject do you study, or what job do you do?", "Why did you choose it?", "What is the most difficult part of it?"]}, {"topic": "mornings", "questions": ["Are you a morning person?", "What do you usually do first thing in the morning?", "Is your morning routine different at the weekend?"]}], "part2": {"topic": "a job you would like", "cue": "Describe a job you would like to do in the future.", "points": ["what the job is", "what the job involves", "what you would need to do to get it"], "explain": "and explain why you would like to do this job.", "rounding": "Do any of your friends want to do the same job?"}, "part3": {"topic": "work and careers", "questions": ["What do most young people in your country look for in a job?", "Is it better to stay in one job for a long time or to change jobs often?", "How has technology changed the way people work?", "Should people be paid according to how hard they work or how useful their work is?", "What kinds of jobs do you think will disappear in the future?"]}}'::jsonb, now() + interval '2 seconds') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-07', 'Nature and the environment', '{"part1": [{"topic": "plants and flowers", "questions": ["Do you have any plants in your home?", "Did you grow any plants when you were a child?", "Do people in your country often give flowers as gifts?"]}, {"topic": "the weather", "questions": ["What is the weather like where you live?", "Which season do you like best?", "Does the weather affect your mood?"]}], "part2": {"topic": "a natural place", "cue": "Describe a natural place that you enjoyed visiting, such as a forest, mountain or lake.", "points": ["where it is", "when you went there", "what you did there"], "explain": "and explain why you enjoyed visiting this place.", "rounding": "Would you recommend this place to other people?"}, "part3": {"topic": "the natural environment", "questions": ["Why is it important for children to spend time in nature?", "What are the main environmental problems in your country?", "Who should be responsible for protecting the environment: individuals or governments?", "Can tourism help to protect natural areas?", "Do you think cities will become greener in the future?"]}}'::jsonb, now() + interval '3 seconds') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-08', 'Communication and technology', '{"part1": [{"topic": "your phone", "questions": ["How often do you use your phone?", "What do you mainly use it for?", "Could you live without a mobile phone?"]}, {"topic": "friends", "questions": ["How do you usually keep in touch with your friends?", "Do you prefer to meet friends at home or outside?", "Have you kept in touch with your school friends?"]}], "part2": {"topic": "an important conversation", "cue": "Describe an important conversation you had with someone.", "points": ["who you talked to", "what you talked about", "where the conversation took place"], "explain": "and explain why this conversation was important to you.", "rounding": "Do you often have serious conversations like this?"}, "part3": {"topic": "communication", "questions": ["How has the internet changed the way people communicate?", "Is face-to-face communication more valuable than online communication?", "Why do some people find it difficult to express their opinions?", "What communication skills are most important in the workplace?", "Do you think people will write fewer letters and emails in the future?"]}}'::jsonb, now() + interval '4 seconds') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-09', 'Food and celebrations', '{"part1": [{"topic": "cooking", "questions": ["How often do you cook?", "What is the first dish you learned to cook?", "Do you prefer home-cooked food or restaurant food?"]}, {"topic": "celebrations", "questions": ["What is the most important celebration in your country?", "How do you usually celebrate your birthday?", "Do you like big parties?"]}], "part2": {"topic": "a special meal", "cue": "Describe a special meal you had to celebrate something.", "points": ["what the occasion was", "where you had the meal", "who you had it with"], "explain": "and explain why this meal was special to you.", "rounding": "Do you still celebrate this occasion in the same way?"}, "part3": {"topic": "food and traditions", "questions": ["How important is traditional food in your country today?", "Why do people often celebrate special occasions with food?", "Has fast food changed the way families eat together?", "Should schools teach children about healthy eating?", "Will people eat very different food in fifty years’ time?"]}}'::jsonb, now() + interval '5 seconds') ON CONFLICT (id) DO NOTHING;
INSERT INTO speaking_mock_sets (id, title, content, created_at) VALUES ('sm-10', 'Learning and memory', '{"part1": [{"topic": "your school days", "questions": ["What did you like most about your school?", "Which subject did you find most difficult?", "Do you still keep in touch with any of your teachers?"]}, {"topic": "remembering things", "questions": ["Are you good at remembering names?", "How do you remember important dates?", "Do you write lists?"]}], "part2": {"topic": "a lesson you remember", "cue": "Describe a lesson or class that you remember well.", "points": ["what the lesson was about", "who taught it", "what happened during the lesson"], "explain": "and explain why you remember it.", "rounding": "Do you think you learned something useful that day?"}, "part3": {"topic": "education and learning", "questions": ["What makes a good teacher?", "Is it better for children to learn through play or through formal lessons?", "How has technology changed the way students learn?", "Should older people continue to study?", "Do exams show how much a student really knows?"]}}'::jsonb, now() + interval '6 seconds') ON CONFLICT (id) DO NOTHING;
